VALUES('14000000-0000-4000-8000-000000000002','hse.attention.direct-structured-self-report',1,'hse.attention',1,'CALIBRATED','PRODUCTION','QANDEEL_HIM_GOVERNANCE','ISSUE_60_HSE_ATTENTION_MEASUREMENT_MODEL_V1','DIRECT_STRUCTURED_SELF_REPORT','hse.attention.ordinal-5.v1','{"required":["measurementObservation","authorizedContext"]}'::jsonb,'FIRST_CLASS_AUTHORIZED_CONTEXT_HIM_MEASUREMENT_OBSERVATION_V1',ARRAY['SITUATION','CONVERSATION_SESSION','DECISION'],'UNASSESSED','UNASSESSED_PRESERVE_CONFLICT','UNRESOLVED_METRIC_CONFIDENCE','hse-attention-direct-structured-v1','2026-08-23T00:00:00Z','2026-08-23T00:00:00Z');
